// SVG weapon shape generators — 128×128 canvas
const WEAPON_SVG_SHAPES = {
  iron_sword(x, y, s) {
    const bw = 8*s, bh = 48*s, gw = 24*s, gh = 6*s, hw = 6*s, hh = 14*s;
    return `<rect x="${x-bw/2}" y="${y-bh}" width="${bw}" height="${bh}" rx="2" fill="#b0bec5" stroke="#78909c" stroke-width="1.2"/>` +
           `<rect x="${x-gw/2}" y="${y-4*s}" width="${gw}" height="${gh}" rx="2" fill="#8d6e63"/>` +
           `<rect x="${x-hw/2}" y="${y}" width="${hw}" height="${hh}" rx="2" fill="#5d4037"/>`;
  },
  iron_shield(x, y, s) {
    const w = 32*s, h = 40*s;
    return `<rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="${8*s}" fill="#607d8b" stroke="#455a64" stroke-width="2"/>` +
           `<rect x="${x-5*s}" y="${y-10*s}" width="${10*s}" height="${20*s}" rx="2" fill="#ffd54f" opacity="0.7"/>` +
           `<rect x="${x-10*s}" y="${y-5*s}" width="${20*s}" height="${10*s}" rx="2" fill="#ffd54f" opacity="0.7"/>`;
  },
  revolver_r(x, y, s) {
    const bw = 36*s, bh = 8*s, gh = 16*s, gw = 8*s;
    return `<rect x="${x-4*s}" y="${y-bh/2}" width="${bw}" height="${bh}" rx="3" fill="#546e7a" stroke="#37474f" stroke-width="1.2"/>` +
           `<rect x="${x}" y="${y+2*s}" width="${gw}" height="${gh}" rx="2" fill="#4e342e"/>` +
           `<circle cx="${x+28*s}" cy="${y}" r="${4*s}" fill="#37474f"/>`;
  },
  revolver_l(x, y, s) {
    const bw = 36*s, bh = 8*s, gh = 16*s, gw = 8*s;
    return `<rect x="${x-32*s}" y="${y-bh/2}" width="${bw}" height="${bh}" rx="3" fill="#546e7a" stroke="#37474f" stroke-width="1.2"/>` +
           `<rect x="${x-8*s}" y="${y+2*s}" width="${gw}" height="${gh}" rx="2" fill="#4e342e"/>` +
           `<circle cx="${x-28*s}" cy="${y}" r="${4*s}" fill="#37474f"/>`;
  },
  arcane_staff(x, y, s) {
    const sw = 6*s, sh = 60*s, orb = 10*s;
    return `<rect x="${x-sw/2}" y="${y-sh}" width="${sw}" height="${sh}" rx="2" fill="#6d4c41"/>` +
           `<circle cx="${x}" cy="${y-sh+4*s}" r="${orb}" fill="#9c27b0" opacity="0.85"/>` +
           `<circle cx="${x}" cy="${y-sh+4*s}" r="${5*s}" fill="#e1bee7" opacity="0.6"/>`;
  },
  healing_staff(x, y, s) {
    const sw = 6*s, sh = 56*s, gem = 9*s;
    return `<rect x="${x-sw/2}" y="${y-sh}" width="${sw}" height="${sh}" rx="2" fill="#a1887f"/>` +
           `<circle cx="${x}" cy="${y-sh+4*s}" r="${gem}" fill="#26a69a" opacity="0.85"/>` +
           `<circle cx="${x}" cy="${y-sh+4*s}" r="${4.4*s}" fill="#80cbc4" opacity="0.6"/>`;
  },
  combat_knife(x, y, s) {
    const bw = 8*s, bh = 28*s, hw = 6*s, hh = 12*s;
    return `<rect x="${x-bw/2}" y="${y-bh}" width="${bw}" height="${bh}" rx="2" fill="#90a4ae" stroke="#607d8b" stroke-width="1.2"/>` +
           `<rect x="${x-hw/2}" y="${y}" width="${hw}" height="${hh}" rx="2" fill="#3e2723"/>`;
  },
  frag_bomb(x, y, s) {
    const r = 14*s;
    return `<circle cx="${x}" cy="${y}" r="${r}" fill="#455a64" stroke="#37474f" stroke-width="2"/>` +
           `<rect x="${x-3*s}" y="${y-r-8*s}" width="${6*s}" height="${10*s}" rx="2" fill="#8d6e63"/>` +
           `<line x1="${x}" y1="${y-r-8*s}" x2="${x+8*s}" y2="${y-r-16*s}" stroke="#ff9800" stroke-width="${4*s}" stroke-linecap="round"/>`;
  }
};

// Map equipment IDs to weapon shape keys
const EQUIP_TO_WEAPON = {
  'iron_sword': 'iron_sword', 'iron_sword_l': 'iron_sword',
  'iron_shield': 'iron_shield', 'iron_shield_r': 'iron_shield',
  'revolver_r': 'revolver_r', 'revolver_l': 'revolver_l',
  'arcane_staff': 'arcane_staff', 'arcane_staff_r': 'arcane_staff',
  'healing_staff': 'healing_staff', 'healing_staff_l': 'healing_staff',
  'combat_knife': 'combat_knife', 'combat_knife_l': 'combat_knife',
  'frag_bomb': 'frag_bomb', 'frag_bomb_r': 'frag_bomb'
};

function generateWeaponSvg(weaponId, x, y, scale) {
  const shapeKey = EQUIP_TO_WEAPON[weaponId];
  if (!shapeKey || !WEAPON_SVG_SHAPES[shapeKey]) return null;
  const shapes = WEAPON_SVG_SHAPES[shapeKey](x, y, scale);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" width="128" height="128">${shapes}</svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

(function populateWeaponSprites() {
  const handLItems = new Set(['iron_shield', 'revolver_l', 'arcane_staff', 'healing_staff_l', 'combat_knife_l', 'frag_bomb']);
  const racesNeedingAllWeapons = ['ai', 'fairy', 'ghost', 'grey', 'martian', 'orb of light', 'shadow entity'];
  const newMirroredItems = ['iron_sword_l', 'iron_shield_r', 'arcane_staff_r', 'healing_staff_l', 'combat_knife_l', 'frag_bomb_r'];
  const originalWeapons = ['iron_sword', 'iron_shield', 'revolver_r', 'revolver_l', 'arcane_staff', 'healing_staff', 'combat_knife', 'frag_bomb'];
  const allRaces = Object.keys(RACE_WEAPON_ANCHORS);
  const s = 1.0;
  for (const race of racesNeedingAllWeapons) {
    const anchor = RACE_WEAPON_ANCHORS[race];
    if (!anchor) continue;
    const [lx, ly, rx, ry] = anchor;
    for (const wid of originalWeapons) {
      const key = race + '_' + wid;
      if (EQUIP_SPRITES[key]) continue;
      const isLeft = handLItems.has(wid);
      const svg = generateWeaponSvg(wid, isLeft ? lx : rx, isLeft ? ly : ry, s);
      if (svg) EQUIP_SPRITES[key] = svg;
    }
  }
  for (const race of allRaces) {
    const anchor = RACE_WEAPON_ANCHORS[race];
    if (!anchor) continue;
    const [lx, ly, rx, ry] = anchor;
    for (const wid of newMirroredItems) {
      const key = race + '_' + wid;
      if (EQUIP_SPRITES[key]) continue;
      const isLeft = handLItems.has(wid);
      const svg = generateWeaponSvg(wid, isLeft ? lx : rx, isLeft ? ly : ry, s);
      if (svg) EQUIP_SPRITES[key] = svg;
    }
  }
})();

const EQUIP_RACE_COMPAT = {
  'nordic':     { fallback: 'homosapien', slots: 'all' },
  'annunaki':   { fallback: 'homosapien', slots: 'all' },
  'skinwalker': { fallback: 'homosapien', slots: 'all' },
  'zombie':     { fallback: 'homosapien', slots: ['head', 'handL', 'handR', 'boots'] },
  'skeleton':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR', 'boots'] },
  'demon':      { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'succubus':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'angel':      { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'seraphim':   { fallback: 'homosapien', slots: ['head', 'handL', 'handR'] },
  'android':    { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'robot':      { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'mech':       { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'bigfoot':    { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'giant':      { fallback: 'homosapien', slots: ['handL', 'handR'] },
  'reptilian':  { fallback: 'homosapien', slots: ['handL', 'handR'] },
};

function resolveEquipSprite(race, itemId) {
  if (!race || !itemId) return null;
  const directKey = race + '_' + itemId;
  if (EQUIP_SPRITES[directKey]) return EQUIP_SPRITES[directKey];
  const compat = EQUIP_RACE_COMPAT[race];
  if (!compat) return null;
  const def = (typeof EQUIP_DEFS !== 'undefined') ? EQUIP_DEFS[itemId] : null;
  if (def && compat.slots !== 'all') {
    if (!compat.slots.includes(def.slot)) return null;
  }
  const fallbackKey = compat.fallback + '_' + itemId;
  return EQUIP_SPRITES[fallbackKey] || null;
}

